CREATE DATABASE IF NOT EXISTS sa_recovery CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sa_recovery;
CREATE TABLE roles (id TINYINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(32) NOT NULL UNIQUE);
INSERT INTO roles(name) VALUES ('admin'),('clinician'),('coach'),('athlete');
CREATE TABLE users (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, role_id TINYINT UNSIGNED NOT NULL, full_name VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE sports (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE, active TINYINT(1) DEFAULT 1);
CREATE TABLE teams (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT, sport_id INT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, coach_user_id BIGINT UNSIGNED NULL, FOREIGN KEY(sport_id) REFERENCES sports(id), FOREIGN KEY(coach_user_id) REFERENCES users(id));
CREATE TABLE athlete_profiles (user_id BIGINT UNSIGNED PRIMARY KEY, student_id VARCHAR(40) NOT NULL UNIQUE, sport_id INT UNSIGNED NULL, department VARCHAR(120), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(sport_id) REFERENCES sports(id));
CREATE TABLE team_memberships (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, team_id INT UNSIGNED NOT NULL, athlete_user_id BIGINT UNSIGNED NOT NULL, start_date DATE NOT NULL, end_date DATE NULL, FOREIGN KEY(team_id) REFERENCES teams(id), FOREIGN KEY(athlete_user_id) REFERENCES users(id), UNIQUE(team_id, athlete_user_id));
CREATE TABLE recovery_cases (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, athlete_user_id BIGINT UNSIGNED NOT NULL, assigned_clinician_id BIGINT UNSIGNED NULL, summary VARCHAR(180) NOT NULL, concern TEXT NOT NULL, status ENUM('submitted','under_review','monitoring','closed') NOT NULL DEFAULT 'submitted', reported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(athlete_user_id) REFERENCES users(id), FOREIGN KEY(assigned_clinician_id) REFERENCES users(id), INDEX(status,reported_at));
CREATE TABLE case_reviews (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, case_id BIGINT UNSIGNED NOT NULL, reviewer_id BIGINT UNSIGNED NOT NULL, outcome VARCHAR(60) NOT NULL, note TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(case_id) REFERENCES recovery_cases(id), FOREIGN KEY(reviewer_id) REFERENCES users(id));
CREATE TABLE recovery_milestones (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, case_id BIGINT UNSIGNED NOT NULL, label VARCHAR(140) NOT NULL, status ENUM('pending','documented','reviewed') DEFAULT 'pending', note TEXT, recorded_by BIGINT UNSIGNED NOT NULL, recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(case_id) REFERENCES recovery_cases(id), FOREIGN KEY(recorded_by) REFERENCES users(id));
CREATE TABLE follow_up_appointments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, case_id BIGINT UNSIGNED NOT NULL, scheduled_at DATETIME NOT NULL, purpose VARCHAR(180) NOT NULL, status ENUM('scheduled','completed','cancelled','missed') DEFAULT 'scheduled', created_by BIGINT UNSIGNED NOT NULL, FOREIGN KEY(case_id) REFERENCES recovery_cases(id));
CREATE TABLE clearance_records (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, case_id BIGINT UNSIGNED NOT NULL, clinician_id BIGINT UNSIGNED NOT NULL, decision ENUM('cleared','not_cleared','restricted') NOT NULL, valid_until DATE NULL, note TEXT, recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(case_id) REFERENCES recovery_cases(id), FOREIGN KEY(clinician_id) REFERENCES users(id));
CREATE TABLE participation_reviews (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, case_id BIGINT UNSIGNED NOT NULL, reviewer_id BIGINT UNSIGNED NOT NULL, status ENUM('pending','approved','not_approved') DEFAULT 'pending', note VARCHAR(500), reviewed_at TIMESTAMP NULL, FOREIGN KEY(case_id) REFERENCES recovery_cases(id));
CREATE TABLE dss_rules (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT, version VARCHAR(32) NOT NULL, required_milestone_count SMALLINT UNSIGNED NOT NULL DEFAULT 1, active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO dss_rules(version,required_milestone_count) VALUES('1.0',1);
CREATE TABLE dss_evaluations (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, case_id BIGINT UNSIGNED NOT NULL, rule_id INT UNSIGNED NOT NULL, outcome ENUM('documentation_complete','documentation_incomplete','review_required') NOT NULL, explanation TEXT NOT NULL, evaluated_by BIGINT UNSIGNED NOT NULL, evaluated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(case_id) REFERENCES recovery_cases(id), FOREIGN KEY(rule_id) REFERENCES dss_rules(id), FOREIGN KEY(evaluated_by) REFERENCES users(id));
CREATE TABLE dss_evaluation_details (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, evaluation_id BIGINT UNSIGNED NOT NULL, check_name VARCHAR(100) NOT NULL, passed TINYINT(1) NOT NULL, detail VARCHAR(500) NOT NULL, FOREIGN KEY(evaluation_id) REFERENCES dss_evaluations(id));
CREATE TABLE notifications (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, message VARCHAR(500) NOT NULL, read_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE activity_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80), entity_id BIGINT UNSIGNED NULL, details VARCHAR(500), ip_address VARCHAR(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(created_at), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE backup_records (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, filename VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE system_settings (`key` VARCHAR(100) PRIMARY KEY, value TEXT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE document_metadata (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, case_id BIGINT UNSIGNED NOT NULL, uploaded_by BIGINT UNSIGNED NOT NULL, label VARCHAR(150) NOT NULL, private_path VARCHAR(500) NOT NULL, status ENUM('requested','received','verified') DEFAULT 'requested', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(case_id) REFERENCES recovery_cases(id));
